import{At as e,Et as t,ft as n,ht as r,lt as i,mt as a,n as o}from"./chunks/framework.CK3_e0nb.js";var s=JSON.parse(`{"title":"午后的一杯清茶","description":"午后三点，阳光恰好斜斜地落在茶桌的一角。烧上一壶山泉水，取少许白茶投入白瓷杯中，静候水沸。 水注倾泻入杯的瞬间，干燥的茶叶在热水中翻滚舒展，茶香随之袅袅升起。初品微苦，继而甘醇从舌根缓缓蔓延开来，回味悠长。在这个事事追求效率与反馈的时代，能够慢下节奏，用半个小时认真泡一杯茶，已然成了一种难得的奢侈。","frontmatter":{"id":"7f60e9","title":"午后的一杯清茶","datetime":"2026-10-05 10:00:00","category":"散文","tags":["生活","慢调"]},"headers":[],"relativePath":"essays/7f60e9.md","filePath":"essays/essay-05.md","lastUpdated":1792855556000}`),c={name:`essays/7f60e9.md`};function l(o,s,c,l,u,d){let f=e(`PostMeta`);return t(),n(`div`,null,[s[0]||=i(`h1`,{id:`午后的一杯清茶`,tabindex:`-1`},[a(`午后的一杯清茶 `),i(`a`,{class:`header-anchor`,href:`#午后的一杯清茶`,"aria-label":`Permalink to “午后的一杯清茶”`},`​`)],-1),r(f),s[1]||=i(`p`,null,`午后三点，阳光恰好斜斜地落在茶桌的一角。烧上一壶山泉水，取少许白茶投入白瓷杯中，静候水沸。`,-1),s[2]||=i(`p`,null,`水注倾泻入杯的瞬间，干燥的茶叶在热水中翻滚舒展，茶香随之袅袅升起。初品微苦，继而甘醇从舌根缓缓蔓延开来，回味悠长。在这个事事追求效率与反馈的时代，能够慢下节奏，用半个小时认真泡一杯茶，已然成了一种难得的奢侈。茶道并不在乎器具的贵重与否，更在于一份向内自省的心境。静坐片刻，看着杯中浮沉的叶片，纷乱的念头逐渐尘埃落定。生活如同一壶茶，苦涩有时，甘甜亦有时，唯有细细慢品方能体味真意。`,-1)])}var u=o(c,[[`render`,l]]);export{s as __pageData,u as default};